144	export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" }) {
145	  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
146	  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
147	                               staleTime: 30_000, placeholderData: (prev) => prev });
148	  const [hoverKey, setHoverKey] = useState<string | null>(null);
149	  const activity = useActivity();
150	  // when a stage finishes, show its output without a reload
151	  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
152	  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
153	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
154	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
155	  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
156	  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
157	  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
158	    const vals = new Set(f[d]);
159	    if (vals.has(v)) vals.delete(v); else vals.add(v);
160	    const next = { ...f, [d]: vals };
161	    if (!vals.size) delete next[d];
162	    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
163	  });
164	  const clear = (d?: Dim) => setChosen(({ f, order }) => {
165	    if (!d) return { f: {}, order: [] };
166	    const next = { ...f }; delete next[d];
167	    return { f: next, order: order.filter((x) => x !== d) };
168	  });
169	  const [hover, setHover] = useState<Hover | null>(null);
170	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
171	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
172	
173	  // the filters work on page 1 only; page 2 hides them, so nothing stays filtered there unseen
174	  const filter = useMemo<Filter | null>(() => (mode === "scan" && isActive(chosen.f) ? chosen.f : null), [mode, chosen]);
175	  const mask = useMemo(() => (points.data ? commentMask(points.data, filter) : new Uint8Array(0)), [points.data, filter]);
176	
177	  useEffect(() => {
178	    const onKey = (e: KeyboardEvent) => {
179	      if (e.key !== "Escape") return;
180	      if (selected) setSelected(null); else clear();
181	    };
182	    window.addEventListener("keydown", onKey);
183	    return () => window.removeEventListener("keydown", onKey);
184	  }, [selected]);
185	  useEffect(() => { setSelected(null); setHover(null); }, [mode]);
186	
187	  return (
188	    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
189	      <div className="scan-canvas">
190	        {points.data && (
191	          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 60 }}
192	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
193	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
194	                  onPointerMissed={() => setSelected(null)}>
195	            <Suspense fallback={null}>
196	              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
197	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
198	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
199	                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
200	                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter} />
201	            </Suspense>
202	          </Canvas>
203	        )}
204	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
205	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
206	      </div>
207	
208	      {mode === "scan" ? (
209	        <div className="hud-tl">
210	          <Readout points={points.data} mask={mask} filter={filter} />
211	          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
212	                                     onToggle={toggle} onClear={clear} />}
213	        </div>
214	      ) : <Funnel data={structure.data} />}
215	      {mode === "structure" && <AgentPanel />}
216	      <PageSwitch />
217	
218	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
219	      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
220	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
221	    </main>
222	  );
223	}
