249	/* ------------------------------------------------------------------------------------------- filters */
250	// One chip per dimension, under the readout. At rest only the dimensions in use show (their chosen values and an ×),
251	// plus a "Filter" hint; hovering the row reveals the others. Hovering a chip opens its values; choosing one closes the
252	// list again, so only the choice stays. Dimensions in use come first, in the order they were set, so revealing the
253	// rest never moves them. Car and market filter every data type; the other chips belong to one type and carry its glyph
254	// (comments: channel, label, engine; research: trust; study: result; options: category; sales: year).
255	const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
256	const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";
257	
258	interface FilterProps {
259	  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
260	  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
261	}
262	
263	function FilterBar(p: FilterProps) {
264	  const [reveal, setReveal] = useState(false);
265	  const [open, setOpen] = useState<Dim | null>(null);
266	  const timer = useRef<number | undefined>(undefined);
267	  const show = () => { window.clearTimeout(timer.current); setReveal(true); };
268	  const hide = () => { window.clearTimeout(timer.current); timer.current = window.setTimeout(() => { setReveal(false); setOpen(null); }, 240); };
269	  useEffect(() => () => window.clearTimeout(timer.current), []);
270	  const active = p.order.filter((d) => p.filter[d]?.size);
271	  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
272	  return (
273	    <div className="filters" role="toolbar" aria-label="Filter the scan"
274	         onPointerEnter={(e) => isMouse(e) && show()} onPointerLeave={(e) => isMouse(e) && hide()}
275	         onFocus={show} onBlur={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node | null)) hide(); }}>
276	      {[...active, ...(reveal ? idle : [])].map((d) => (
277	        <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
278	      ))}
279	      {!reveal && idle.length > 0 && (
280	        <button className="filters-hint" onClick={() => setReveal(true)}><SlidersHorizontal size={12} aria-hidden />Filter</button>
281	      )}
282	      {reveal && active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
283	    </div>
284	  );
285	}
