287	function Chip({ dim, open, setOpen, ...p }: FilterProps & { dim: Dim; open: boolean; setOpen: (o: boolean) => void }) {
288	  const meta = DIMS.find((d) => d.id === dim)!;
289	  const chosen = p.filter[dim];
290	  const values = useMemo(() => (open ? keyValues(dim, p.points, p.sources, p.position, p.filter) : []),
291	    [open, dim, p.points, p.sources, p.position, p.filter]);
292	  const max = Math.max(1, ...values.map((v) => v.n));
293	  const names = [...(chosen ?? [])].map((v) => valueName(dim, v));
294	  return (
295	    <div className="fchip" data-on={chosen?.size ? "" : undefined} data-open={open ? "" : undefined}
296	         onPointerEnter={(e) => isMouse(e) && setOpen(true)} onPointerLeave={(e) => isMouse(e) && setOpen(false)}>
297	      <button className="fchip-btn" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
298	        {meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}
299	        <span className="fchip-dim">{meta.name}</span>
300	        {names.length > 0 && <span className="fchip-val">{names[0]}{names.length > 1 ? ` +${names.length - 1}` : ""}</span>}
301	      </button>
302	      {chosen?.size ? <button className="fchip-x" aria-label={`Clear ${meta.name} filter`} onClick={() => p.onClear(dim)}><X size={12} /></button> : null}
303	      {open && (
304	        <div className="fpop">
305	          <div className="fpop-panel" role="listbox" aria-multiselectable aria-label={meta.name}>
306	            <p className="fpop-scope">{meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}{SCOPE_NOTE[meta.scope]}</p>
307	            {values.map(({ v, name, n }) => (
308	              <button key={v} role="option" aria-selected={!!chosen?.has(v)} onClick={() => { p.onToggle(dim, v); setOpen(false); }}>
309	                <span className="fpop-name">{name}</span>
310	                <span className="fpop-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
311	                <span className="fpop-n">{fmt(n)}</span>
312	              </button>
313	            ))}
314	          </div>
315	        </div>
316	      )}
317	    </div>
318	  );
319	}
