// Filtering the scan. Any number of dimensions at once; within a dimension the chosen values are alternatives (OR),
// across dimensions they all have to hold (AND). Car and market exist on every data type, so they filter the whole
// volume; the rest belong to one type and leave the others alone. Items with no value for a global dimension (options
// have no market, global research has none) stay visible: they apply everywhere.
import type { OptionItem, PointsPayload, ResearchItem, SalesRow, SourcesPayload, StudyItem } from "@/lib/types";
import { CARS, CAR_NAME, MARKET_NAME } from "./layout";

export type Dim = "car" | "market" | "channel" | "type" | "engine" | "tier" | "rating" | "category" | "year";
export type Scope = "all" | "comment" | "research" | "study" | "option" | "sales";
export const DIMS: { id: Dim; name: string; scope: Scope }[] = [
  { id: "car", name: "Car", scope: "all" }, { id: "market", name: "Market", scope: "all" },
  { id: "channel", name: "Channel", scope: "comment" }, { id: "type", name: "Label", scope: "comment" },
  { id: "engine", name: "Engine", scope: "comment" },
  { id: "tier", name: "Trust", scope: "research" }, { id: "rating", name: "Study result", scope: "study" },
  { id: "category", name: "Category", scope: "option" }, { id: "year", name: "Sales year", scope: "sales" },
];
export const SCOPE_NOTE: Record<Scope, string> = {
  all: "Filters all data", comment: "Customer comments only", research: "Web research only", study: "Customer study only",
  option: "Equipment options only", sales: "BMW sales volumes only",
};

/** The chosen values per dimension; a dimension without a set (or with an empty one) is not filtered. */
export type Filter = Partial<Record<Dim, Set<string>>>;

const NONE = "∅";
const key = (v: string | null | undefined) => v ?? NONE;
const COMMENT_DIMS = ["car", "market", "channel", "type", "engine"] as const;
type CommentDim = (typeof COMMENT_DIMS)[number];
const isCommentDim = (d: Dim): d is CommentDim => (COMMENT_DIMS as readonly Dim[]).includes(d);
const on = (f: Filter | null, d: Dim) => (f?.[d]?.size ? f[d]! : null);

export const isActive = (f: Filter | null) => !!f && DIMS.some((d) => on(f, d.id));
export const without = (f: Filter | null, d: Dim): Filter => { const g = { ...f }; delete g[d]; return g; };

/** A study item's result against its car × market's average: half a standard deviation either way counts. */
export const ratingOf = (s: StudyItem) => ((s.z ?? 0) >= 0.5 ? "above" : (s.z ?? 0) <= -0.5 ? "below" : "around");
const yearOf = (r: SalesRow) => String(r.year);

/** The 5 Series' China research is about the long-wheelbase G68 (as on the rings). */
export const researchCars = (it: ResearchItem) => it.cars.map((c) => (c === "G60" && it.region === "CN" ? "G68" : c));

export function passResearch(f: Filter | null, it: ResearchItem) {
  const car = on(f, "car"), market = on(f, "market"), tier = on(f, "tier");
  return (!car || researchCars(it).some((c) => car.has(c)))
    && (!market || it.market == null || market.has(it.market))
    && (!tier || tier.has(key(it.tier)));
}
export function passStudy(f: Filter | null, s: StudyItem) {
  const car = on(f, "car"), market = on(f, "market"), rating = on(f, "rating");
  return (!car || car.has(s.car)) && (!market || market.has(s.market)) && (!rating || rating.has(ratingOf(s)));
}
export function passOption(f: Filter | null, o: OptionItem) {
  const car = on(f, "car"), category = on(f, "category");
  return (!car || car.has(o.car)) && (!category || category.has(key(o.category)));
}
export function passSales(f: Filter | null, r: SalesRow) {
  const car = on(f, "car"), market = on(f, "market"), year = on(f, "year");
  return (!car || car.has(r.car)) && (!market || market.has(r.market)) && (!year || year.has(yearOf(r)));
}

/** 1 = the comment passes every comment dimension that is filtered. */
export function commentMask(points: PointsPayload, f: Filter | null) {
  const m = new Uint8Array(points.n).fill(1);
  for (const d of COMMENT_DIMS) {
    const vals = on(f, d);
    if (!vals) continue;
    const col = points.cols[d], dict = points.dict[d] as (string | null)[];
    for (let i = 0; i < points.n; i++) if (m[i] && !(col[i] >= 0 && vals.has(key(dict[col[i]])))) m[i] = 0;
  }
  return m;
}

const TIER_NAME: Record<string, string> = { T1: "T1 · official", T2: "T2 · press & analysts", T3: "T3 · forums & social" };
const RATING_NAME: Record<string, string> = { above: "Above average", around: "Around average", below: "Below average" };

/** The values a dimension offers, with how many items carry each one at this checkpoint, given the other filters. */
export function keyValues(dim: Dim, points: PointsPayload, src: SourcesPayload | undefined, position: number, f: Filter | null = null) {
  const rest = without(f, dim);
  const n = new Map<string, number>();
  const add = (v: string | null | undefined) => n.set(key(v), (n.get(key(v)) ?? 0) + 1);
  if (isCommentDim(dim)) {
    const mask = commentMask(points, rest);
    const col = points.cols[dim], dict = points.dict[dim] as (string | null)[], cps = points.cols.cp;
    for (let i = 0; i < points.n; i++) if (mask[i] && col[i] >= 0 && cps[i] <= position) add(dict[col[i]]);
  }
  const research = (src?.research ?? []).filter((r) => (position > 1 || !r.new) && passResearch(rest, r));
  const study = (src?.study ?? []).filter((s) => passStudy(rest, s));
  const options = (src?.options ?? []).filter((o) => passOption(rest, o));
  const sales = (src?.sales ?? []).filter((r) => r.units && r.units > 0 && passSales(rest, r));   // as drawn: one bar per figure
  if (dim === "car") {
    for (const r of research) new Set(researchCars(r)).forEach(add);
    for (const s of study) add(s.car);
    for (const o of options) add(o.car);
    for (const r of sales) add(r.car);
  }
  if (dim === "market") {
    for (const r of research) if (r.market) add(r.market);
    for (const s of study) add(s.market);
    for (const r of sales) add(r.market);
  }
  if (dim === "tier") for (const r of research) add(r.tier);
  if (dim === "category") for (const o of options) add(o.category);
  if (dim === "rating") for (const s of study) add(ratingOf(s));
  if (dim === "year") for (const r of sales) add(yearOf(r));

  // a chosen value stays listed even when the other filters leave nothing for it, so it can be unchosen
  const chosen = on(f, dim);
  const order: string[] =
    dim === "car" ? [...CARS] : dim === "market" ? ["EU", "US", "CN", "RoW"] : dim === "tier" ? ["T1", "T2", "T3"]
      : dim === "rating" ? ["above", "around", "below"] : dim === "year" ? [...new Set((src?.sales ?? []).map(yearOf))].sort()
      : isCommentDim(dim) ? (points.dict[dim] as (string | null)[]).map(key)
        : [...new Set([...(src?.options ?? []).map((o) => key(o.category))])].sort((a, b) => (n.get(b) ?? 0) - (n.get(a) ?? 0));
  return order.filter((v) => n.get(v) || chosen?.has(v)).map((v) => ({ v, name: valueName(dim, v), n: n.get(v) ?? 0 }));
}

export function valueName(dim: Dim, v: string) {
  if (v === NONE) return dim === "type" ? "Unlabelled" : "Unknown";
  if (dim === "car") return CAR_NAME[v] ?? v;
  if (dim === "market") return MARKET_NAME[v] ?? v;
  if (dim === "tier") return TIER_NAME[v] ?? v;
  if (dim === "rating") return RATING_NAME[v] ?? v;
  if (dim === "year") return v === "2030" ? "2030 forecast" : v;
  return v;
}
// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
import { Suspense, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { Canvas } from "@react-three/fiber";
import { useQuery } from "@tanstack/react-query";
import { ExternalLink, SlidersHorizontal, X } from "lucide-react";
import { api } from "@/lib/api";
import type { Comment, PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
import { AreaBody, ClusterBody, Funnel, SignalList, ThemeBody } from "../structure/panels";
import { AgentPanel, useActivity } from "../structure/AgentPanel";
import { PageSwitch } from "@/components/PageSwitch";
import { useCheckpoint } from "@/state/checkpoint";
import { Scene, TYPE_COLOR, layerOf, studyValue, type Hover } from "./Scene";
import { CAR_NAME, MARKET_NAME } from "./layout";
import { DIMS, SCOPE_NOTE, commentMask, isActive, keyValues, passOption, passResearch, passSales, passStudy, valueName, type Dim, type Filter, type Scope } from "./filter";
import "./scan.css";

const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));


export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" }) {
  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
                               staleTime: 30_000, placeholderData: (prev) => prev });
  const [hoverKey, setHoverKey] = useState<string | null>(null);
  const activity = useActivity();
  // when a stage finishes, show its output without a reload
  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
    const vals = new Set(f[d]);
    if (vals.has(v)) vals.delete(v); else vals.add(v);
    const next = { ...f, [d]: vals };
    if (!vals.size) delete next[d];
    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
  });
  const clear = (d?: Dim) => setChosen(({ f, order }) => {
    if (!d) return { f: {}, order: [] };
    const next = { ...f }; delete next[d];
    return { f: next, order: order.filter((x) => x !== d) };
  });
  const [hover, setHover] = useState<Hover | null>(null);
  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;

  // the filters work on page 1 only; page 2 hides them, so nothing stays filtered there unseen
  const filter = useMemo<Filter | null>(() => (mode === "scan" && isActive(chosen.f) ? chosen.f : null), [mode, chosen]);
  const mask = useMemo(() => (points.data ? commentMask(points.data, filter) : new Uint8Array(0)), [points.data, filter]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (selected) setSelected(null); else clear();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selected]);
  useEffect(() => { setSelected(null); setHover(null); }, [mode]);

  return (
    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
      <div className="scan-canvas">
        {points.data && (
          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 60 }}
                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
                  onPointerMissed={() => setSelected(null)}>
            <Suspense fallback={null}>
              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter} />
            </Suspense>
          </Canvas>
        )}
        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
      </div>

      {mode === "scan" ? (
        <div className="hud-tl">
          <Readout points={points.data} mask={mask} filter={filter} />
          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
                                     onToggle={toggle} onClear={clear} />}
        </div>
      ) : <Funnel data={structure.data} />}
      {mode === "structure" && <AgentPanel />}
      <PageSwitch />

      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
    </main>
  );
}

/* ------------------------------------------------------------------------------------------- glyphs */
type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
const GLYPH_COLOR: Record<GlyphKind, string> = {
  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
};
function Glyph({ kind }: { kind: GlyphKind }) {
  const c = "currentColor";
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
    </svg>
  );
}

/* ------------------------------------------------------------------------------------------- readout */
// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
    </dl>
  );
}

/* ------------------------------------------------------------------------------------------- filters */
// One chip per dimension, under the readout. At rest only the dimensions in use show (their chosen values and an ×),
// plus a "Filter" hint; hovering the row reveals the others. Hovering a chip opens its values; choosing one closes the
// list again, so only the choice stays. Dimensions in use come first, in the order they were set, so revealing the
// rest never moves them. Car and market filter every data type; the other chips belong to one type and carry its glyph
// (comments: channel, label, engine; research: trust; study: result; options: category; sales: year).
const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";

interface FilterProps {
  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
}

function FilterBar(p: FilterProps) {
  const [reveal, setReveal] = useState(false);
  const [open, setOpen] = useState<Dim | null>(null);
  const timer = useRef<number | undefined>(undefined);
  const show = () => { window.clearTimeout(timer.current); setReveal(true); };
  const hide = () => { window.clearTimeout(timer.current); timer.current = window.setTimeout(() => { setReveal(false); setOpen(null); }, 240); };
  useEffect(() => () => window.clearTimeout(timer.current), []);
  const active = p.order.filter((d) => p.filter[d]?.size);
  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
  return (
    <div className="filters" role="toolbar" aria-label="Filter the scan"
         onPointerEnter={(e) => isMouse(e) && show()} onPointerLeave={(e) => isMouse(e) && hide()}
         onFocus={show} onBlur={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node | null)) hide(); }}>
      {[...active, ...(reveal ? idle : [])].map((d) => (
        <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
      ))}
      {!reveal && idle.length > 0 && (
        <button className="filters-hint" onClick={() => setReveal(true)}><SlidersHorizontal size={12} aria-hidden />Filter</button>
      )}
      {reveal && active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
    </div>
  );
}

function Chip({ dim, open, setOpen, ...p }: FilterProps & { dim: Dim; open: boolean; setOpen: (o: boolean) => void }) {
  const meta = DIMS.find((d) => d.id === dim)!;
  const chosen = p.filter[dim];
  const values = useMemo(() => (open ? keyValues(dim, p.points, p.sources, p.position, p.filter) : []),
    [open, dim, p.points, p.sources, p.position, p.filter]);
  const max = Math.max(1, ...values.map((v) => v.n));
  const names = [...(chosen ?? [])].map((v) => valueName(dim, v));
  return (
    <div className="fchip" data-on={chosen?.size ? "" : undefined} data-open={open ? "" : undefined}
         onPointerEnter={(e) => isMouse(e) && setOpen(true)} onPointerLeave={(e) => isMouse(e) && setOpen(false)}>
      <button className="fchip-btn" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
        {meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}
        <span className="fchip-dim">{meta.name}</span>
        {names.length > 0 && <span className="fchip-val">{names[0]}{names.length > 1 ? ` +${names.length - 1}` : ""}</span>}
      </button>
      {chosen?.size ? <button className="fchip-x" aria-label={`Clear ${meta.name} filter`} onClick={() => p.onClear(dim)}><X size={12} /></button> : null}
      {open && (
        <div className="fpop">
          <div className="fpop-panel" role="listbox" aria-multiselectable aria-label={meta.name}>
            <p className="fpop-scope">{meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}{SCOPE_NOTE[meta.scope]}</p>
            {values.map(({ v, name, n }) => (
              <button key={v} role="option" aria-selected={!!chosen?.has(v)} onClick={() => { p.onToggle(dim, v); setOpen(false); }}>
                <span className="fpop-name">{name}</span>
                <span className="fpop-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
                <span className="fpop-n">{fmt(n)}</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------- hover */
const useComment = (id: number | null) =>
  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });

function HoverCard({ hover, points }: { hover: Hover; points: PointsPayload | undefined }) {
  const id = hover.comment != null && points ? points.cols.id[hover.comment] : null;
  const q = useComment(id);
  const left = Math.min(hover.x + 16, window.innerWidth - 336), top = Math.min(hover.y + 16, window.innerHeight - 140);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      {id != null ? (
        <>
          <p>{q.data?.text ?? " "}</p>
          {q.data && (
            <div className="hovercard-meta">
              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
            </div>
          )}
        </>
      ) : (
        <>
          <p>{hover.title}</p>
          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
        </>
.scan { position: fixed; inset: 0; background: var(--void); }
.scan-canvas { position: absolute; inset: 0; }
.scan-canvas canvas { display: block; }
.scan-state { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: 14px; color: var(--ink-3); font-size: var(--t-label); letter-spacing: 0.08em; }
.scan-state.error { color: var(--lost); max-width: 48ch; text-align: center; margin: auto; letter-spacing: 0; }
.scan-pulse { width: 64px; height: 64px; border-radius: 50%; border: 1px solid var(--hair-2); position: relative; }
.scan-pulse::after { content: ""; position: absolute; inset: 0; border-radius: 50%; border-top: 1px solid var(--sweep-hi); animation: spin 1.4s linear infinite; }
@keyframes spin { to { transform: rotate(1turn); } }

/* readout: one named, counted cell per colour in the scene, top-left. Comments and research on the first row, the three
   car-ring types beneath, so it stays clear of the page switch at top centre; one row once the screen is wide enough. */
.hud-tl { position: fixed; top: var(--edge); left: var(--edge); z-index: 15; display: grid; gap: 18px; justify-items: start; }
.readout { display: grid; grid-template-columns: repeat(3, max-content); gap: 16px 32px; margin: 0; pointer-events: none; }
.readout > div:nth-child(3) { grid-column: 1; }
@media (min-width: 1900px) { .readout { grid-template-columns: repeat(5, max-content); } .readout > div:nth-child(3) { grid-column: auto; } }
.readout div { display: grid; gap: 6px; align-content: start; }
.readout dt { display: inline-flex; align-items: center; gap: 7px; }
.readout dd { margin: 0; display: inline-flex; align-items: baseline; gap: 10px; }
.readout .num { font-size: 28px; color: var(--ink); }
.readout dd.readout-pub { gap: 6px; align-items: center; font-size: var(--t-label); color: var(--ink-2); }
.readout-pub i { width: 7px; height: 7px; border-radius: 50%; border: 1.5px solid; flex: none; }
.readout-pub .plus { font-size: var(--t-micro); }
.plus { font-size: var(--t-label); font-weight: 600; color: var(--ink-2); letter-spacing: 0.01em; }
.glyph { color: var(--ink-2); flex: none; }
.glyph-trio { display: inline-flex; gap: 1px; }
.ring-name i { width: 6px; height: 6px; border-radius: 50%; display: inline-block; }

/* ring labels drawn in 3D space */
.ring-label { display: grid; justify-items: center; gap: 2px; white-space: nowrap; pointer-events: none; user-select: none; }
.ring-label b { font-size: var(--t-label); font-weight: 600; color: var(--ink-2); }
.ring-label span { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.06em; }
.ring-sub { font-size: var(--t-micro); color: var(--ink-3); letter-spacing: 0.06em; white-space: nowrap; pointer-events: none; user-select: none; }
.time-label { font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.1em; color: var(--ink-2); white-space: nowrap; pointer-events: none; user-select: none; }

.ring-name { display: inline-flex; align-items: center; gap: 5px; font-size: var(--t-micro); color: var(--ink-2); letter-spacing: 0.06em; white-space: nowrap; pointer-events: none; user-select: none; padding: 1px 5px; background: rgba(0, 0, 0, 0.7); border-radius: 4px; }
.ring-name, .ring-sub, .time-label { transition: opacity 0.6s cubic-bezier(0.33, 1, 0.68, 1); }
.ring-name[data-dim], .ring-sub[data-dim], .time-label[data-dim] { opacity: 0.1; }

/* filters: a chip row under the readout. At rest only the chips in use and a "Filter" hint; hovering reveals the rest. */
.filters { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 28px; max-width: calc(100vw - 2 * var(--edge) - 440px); }
.fchip { position: relative; display: inline-flex; align-items: center; height: 28px; border-radius: 99px; border: 1px solid var(--hair); background: rgba(0, 0, 0, 0.6); transition: border-color var(--fast), background var(--fast); animation: chip-in var(--med) var(--ease); }
@keyframes chip-in { from { opacity: 0; transform: translateY(-3px); } }
.fchip:hover, .fchip[data-open] { border-color: var(--hair-2); background: rgba(255, 255, 255, 0.04); }
.fchip[data-on] { border-color: rgba(77, 148, 255, 0.55); }
.fchip-btn { display: inline-flex; align-items: center; gap: 6px; height: 100%; padding: 0 11px; font-size: var(--t-label); color: var(--ink-2); border-radius: 99px; }
.fchip-btn .glyph { width: 11px; height: 11px; }
.fchip[data-on] .fchip-btn { padding-right: 4px; }
.fchip[data-on] .fchip-dim { color: var(--ink-3); }
.fchip-val { color: var(--ink); white-space: nowrap; }
.fchip-x { display: grid; place-items: center; width: 24px; height: 100%; padding-right: 4px; color: var(--ink-3); border-radius: 0 99px 99px 0; transition: color var(--fast); }
.fchip-x:hover { color: var(--ink); }
.filters-hint { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 4px; font-size: var(--t-label); color: var(--ink-3); transition: color var(--fast); }
.filters-hint:hover { color: var(--ink-2); }
.filters-clear { display: inline-flex; align-items: baseline; gap: 8px; height: 28px; line-height: 28px; padding: 0 6px; font-size: var(--t-label); color: var(--ink-2); animation: chip-in var(--med) var(--ease); }
.filters-clear:hover { color: var(--ink); }

/* a chip's values: a glass list hanging under it (the top padding bridges the gap so the pointer can travel into it) */
.fpop { position: absolute; top: 100%; left: -1px; z-index: 30; padding-top: 6px; }
.fpop-panel {
  width: 280px; max-height: min(420px, calc(100vh - 260px)); overflow: auto; padding: 8px; display: grid; gap: 1px;
  border-radius: var(--r); background: var(--glass); border: 1px solid var(--hair);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 16px 40px rgba(0, 0, 0, 0.5); animation: sheet-in var(--med) var(--ease);
}
.fpop-scope { display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px 6px; font-size: var(--t-micro); color: var(--ink-3); }
.fpop-scope .glyph { width: 11px; height: 11px; }
.fpop-panel button { display: grid; grid-template-columns: 1fr 56px 48px; align-items: center; gap: 10px; padding: 5px 8px; border-radius: 6px; text-align: left; transition: background var(--fast); }
.fpop-panel button:hover { background: rgba(255, 255, 255, 0.06); }
.fpop-name { font-size: var(--t-label); color: var(--ink-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fpop-panel button[aria-selected="true"] .fpop-name { color: var(--ink); }
.fpop-bar { height: 2px; background: var(--hair); border-radius: 1px; overflow: hidden; }
.fpop-bar span { display: block; height: 100%; background: var(--ink-2); transform-origin: 0 50%; }
.fpop-panel button[aria-selected="true"] .fpop-bar span { background: var(--sweep-hi); }
.fpop-n { font-size: var(--t-label); color: var(--ink-2); text-align: right; font-variant-numeric: tabular-nums; }

/* hover card + comment sheet */
.hovercard { position: fixed; z-index: 30; width: 320px; padding: 12px 14px; border-radius: var(--r); background: var(--glass); border: 1px solid var(--hair); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); pointer-events: none; display: grid; gap: 8px; box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 16px 40px rgba(0, 0, 0, 0.5); }
.hovercard p { font-size: 13px; line-height: 1.45; color: var(--ink); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.hovercard-meta { display: flex; align-items: center; gap: 10px; font-size: var(--t-micro); color: var(--ink-3); }
.sheet { position: fixed; top: calc(var(--edge) + 46px); right: var(--edge); z-index: 25; width: min(400px, calc(100vw - 32px)); max-height: calc(100vh - 2 * var(--edge) - 196px); overflow: auto; padding: 28px 26px 24px; border-radius: var(--r); background: var(--glass); border: 1px solid var(--hair); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.6); display: grid; gap: 22px; animation: sheet-in var(--med) var(--ease); }
@keyframes sheet-in { from { opacity: 0; transform: translateY(-6px); } }
.sheet-close { position: absolute; top: 12px; right: 12px; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--ink-3); transition: background var(--fast), color var(--fast); }
.sheet-close:hover { background: rgba(255, 255, 255, 0.07); color: var(--ink); }
.sheet-head { display: grid; gap: 6px; padding-right: 28px; }
.sheet-layer { display: inline-flex; align-items: center; gap: 8px; font-size: var(--t-label); font-weight: 600; color: var(--ink); }
.sheet-what { font-size: var(--t-label); color: var(--ink-3); max-width: 46ch; }
.sheet-title { font-size: var(--t-read); font-weight: 500; line-height: 1.35; color: var(--ink); text-wrap: balance; }
.sheet-figure { display: flex; align-items: baseline; gap: 12px; }
.sheet-figure .num { font-size: 34px; color: var(--ink); }
.sheet-yoy { font-size: var(--t-body); color: var(--ink-2); }
.sheet-link { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; justify-self: start; }
.zbar { position: relative; height: 30px; }
.zbar-mid { position: absolute; left: 50%; top: 0; height: 12px; width: 1px; background: var(--hair-2); }
.zbar-fill { position: absolute; top: 4px; height: 4px; border-radius: 2px; background: var(--ink); }
.zbar-l, .zbar-r { position: absolute; top: 16px; }
.zbar-l { left: 0; } .zbar-r { right: 0; }
.minibars { display: flex; gap: 22px; align-items: flex-end; }
.minibar { display: grid; gap: 6px; justify-items: center; }
.minibar-n { font-size: var(--t-label); color: var(--ink-2); font-variant-numeric: tabular-nums; }
.minibar-col { width: 26px; height: 96px; display: flex; align-items: flex-end; }
.minibar-col span { width: 100%; height: 100%; background: var(--ink-3); border-radius: 2px 2px 0 0; transform-origin: 50% 100%; }
.minibar[data-on] .minibar-col span { background: var(--ink); }
.minibar[data-on] .minibar-n { color: var(--ink); }
.minibar[data-forecast] .minibar-col span { background: transparent; box-shadow: inset 0 0 0 1px var(--ink-2); }
.sheet-quote { margin: 0; font-size: var(--t-read); line-height: 1.5; color: var(--ink); max-width: 60ch; padding-right: 16px; }
.sheet-facts { margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 14px 18px; }
.sheet-facts div { display: grid; gap: 3px; min-width: 0; }
.sheet-facts dd { margin: 0; font-size: 13px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.sheet-ref { letter-spacing: 0.08em; }
.sheet-skel { display: grid; gap: 10px; }
.sheet-skel span { height: 12px; border-radius: 4px; background: rgba(255, 255, 255, 0.06); }
.sheet-skel span:last-child { width: 60%; }

@media (max-width: 760px) {
  .hud-tl { left: 16px; top: 16px; max-width: calc(100vw - 32px); gap: 12px; }
  .readout { display: flex; flex-wrap: wrap; gap: 10px 20px; }
  .filters { max-width: none; }
  .readout .num { font-size: 22px; }
  .sheet { top: auto; bottom: 140px; }
}

