// Bottom-left dock: the Guide explains the screen (a legend drawn with the scene's own marks) and, once something is
// opened, what that kind of item is and how the AI uses it. On Structure it shares the corner with the Agent panel as
// a second tab. The dock folds to its tab row; folded/unfolded is remembered per browser.
import { useEffect, useState, type ReactNode } from "react";
import { ChevronDown } from "lucide-react";
import type { Selection } from "@/lib/types";
import { TYPE_COLOR } from "@/screens/scan/colors";
import "./guide.css";

type Mode = "scan" | "structure";
type MarkKind =
  | "comment" | "research" | "study" | "option" | "sales" | "sales-fc" | "public" | "held" | "new"
  | "improve" | "keep" | "strengthened" | "weakened" | "lost" | "theme" | "area-improve" | "area-keep"
  | "area-emerging" | "area-quality" | "area-new" | "arc" | "arc-contra" | "sector";
interface Row { mark: MarkKind; name: string; text: string }
interface Page { title: string; lead?: string; rows?: Row[]; uses?: string; notes?: string[] }

const BLUE = "#3987e5", INK = "#f2f4f7", AMBER = "#f5a524";

/** The scene's marks in miniature, so the legend looks exactly like what it explains. */
      title: "Requirement area",
      lead: "A product decision area: themes that belong together, with why it matters now and open questions.",
      uses: "Drafting concrete requirements from an area is the next step; the PM decides, never the AI.",
      notes: ["Blue improve, white keep, orange emerging, amber quality hand-over. Outlined = new at this checkpoint."],
    };
  }
}

function GuideBody({ mode, sel }: { mode: Mode; sel: Selection | null }) {
  const page = sel ? forSelection(sel) : mode === "structure" ? STRUCTURE : SCAN;
  return (
    <div className="guide">
      <p className="guide-title">{page.title}</p>
      {page.lead && <p className="guide-lead">{page.lead}</p>}
      {page.uses && <div className="guide-uses"><span className="label">How the AI uses it</span><p>{page.uses}</p></div>}
      {page.rows && (
        <ul className="guide-rows">
          {page.rows.map((r) => <li key={r.name}><Mark kind={r.mark} /><span><b>{r.name}</b> {r.text}</span></li>)}
        </ul>
      )}
      {page.notes && <ul className="guide-notes">{page.notes.map((n) => <li key={n}>{n}</li>)}</ul>}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------- dock */
const FOLD_KEY = "dock.folded";
const readFold = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };

export function Dock({ mode, sel, agent, running = false }: { mode: Mode; sel: Selection | null; agent?: ReactNode; running?: boolean }) {
  // on Structure the live agent stays in view while it works; otherwise the Guide comes first
  const start = () => (mode === "structure" && agent && running ? "agent" : "guide");
  const [tab, setTab] = useState<"guide" | "agent">(start);
  const [folded, setFolded] = useState(readFold);
  useEffect(() => { try { localStorage.setItem(FOLD_KEY, folded ? "1" : "0"); } catch { /* private mode */ } }, [folded]);
  useEffect(() => { setTab(start()); }, [mode]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (sel) setTab("guide"); }, [sel]);      // opening something explains it
  const active = agent ? tab : "guide";
  return (
    <section className="dock" data-folded={folded ? "" : undefined} aria-label="Guide">
      <div className="dock-head">
        <div className="dock-tabs" role="tablist">
          <button role="tab" aria-selected={active === "guide"} onClick={() => { setTab("guide"); setFolded(false); }}>Guide</button>
          {agent && <button role="tab" aria-selected={active === "agent"} onClick={() => { setTab("agent"); setFolded(false); }}>Agent</button>}
        </div>
        <button className="dock-fold" onClick={() => setFolded((f) => !f)} aria-expanded={!folded} aria-label={folded ? "Show" : "Hide"}>
          <ChevronDown size={14} aria-hidden />
        </button>
      </div>
      {!folded && <div className="dock-body">{active === "agent" ? agent : <GuideBody mode={mode} sel={sel} />}</div>}
    </section>
  );
}
/* Bottom-left dock: Guide (and Agent on Structure). Same frameless feathered black field as the audit trail, 300px
   wide like the checkpoint timeline in the opposite corner. */
.dock {
  position: fixed; left: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 12;
  width: 300px; display: grid; gap: 10px; padding: 12px 14px 14px; margin: -12px -14px -14px;
  background: rgba(0, 0, 0, 0.78); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  --feather: linear-gradient(to right, transparent, #000 14px, #000 calc(100% - 14px), transparent), linear-gradient(to bottom, transparent, #000 12px, #000);
  -webkit-mask-image: var(--feather); mask-image: var(--feather); -webkit-mask-composite: source-in; mask-composite: intersect;
  box-sizing: content-box;
}
.dock[data-folded] { background: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; }
.dock-head { display: flex; align-items: center; justify-content: space-between; }
.dock-tabs { display: flex; gap: 16px; }
.dock-tabs button { font-size: var(--t-label); font-weight: 600; color: var(--ink-3); padding: 4px 0; border-bottom: 1px solid transparent; transition: color var(--fast), border-color var(--fast); }
.dock-tabs button:hover { color: var(--ink-2); }
.dock-tabs button[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--sweep-hi); }
.dock[data-folded] .dock-tabs button[aria-selected="true"] { border-bottom-color: transparent; color: var(--ink-2); }
.dock-fold { width: 26px; height: 26px; display: grid; place-items: center; border-radius: 7px; color: var(--ink-3); transition: color var(--fast), background var(--fast), transform var(--fast) var(--ease); }
.dock-fold:hover { color: var(--ink); background: rgba(255, 255, 255, 0.06); }
.dock[data-folded] .dock-fold { transform: rotate(180deg); }
.dock-body { max-height: min(46vh, 420px); overflow-y: auto; margin-right: -6px; padding-right: 6px; animation: dock-in var(--med) var(--ease); }
@keyframes dock-in { from { opacity: 0; transform: translateY(4px); } }

/* the agent panel lives inside the dock on Structure */
.dock .agent { position: static; width: auto; }
.dock .agent-title { display: none; }

/* guide */
.guide { display: grid; gap: 10px; }
.guide-title { font-size: var(--t-label); font-weight: 600; color: var(--ink); }
.guide-lead { font-size: var(--t-label); line-height: 1.5; color: var(--ink-2); }
.guide-uses { display: grid; gap: 4px; }
.guide-uses p { font-size: var(--t-label); line-height: 1.5; color: var(--ink-2); }
.guide-rows { list-style: none; margin: 2px 0 0; padding: 0; display: grid; gap: 8px; }
.guide-rows li { display: grid; grid-template-columns: 18px 1fr; gap: 10px; align-items: start; font-size: var(--t-label); line-height: 1.45; color: var(--ink-3); }
.guide-rows b { font-weight: 500; color: var(--ink-2); }
.gmark { margin-top: 0; }
.guide-notes { list-style: none; margin: 2px 0 0; padding: 8px 0 0; border-top: 1px solid var(--hair); display: grid; gap: 4px; }
.guide-notes li { font-size: var(--t-micro); line-height: 1.45; color: var(--ink-3); }

@media (max-width: 760px) { .dock { left: 16px; right: 16px; width: auto; bottom: 200px; } .dock-body { max-height: 32vh; } }
  const toggleWho = (w: Who) => setHidden((h) => { const n = new Set(h); if (n.has(w)) n.delete(w); else n.add(w); return n; });
  const toggleFold = (id: string) => setExpanded((x) => { const n = new Set(x); if (n.has(id)) n.delete(id); else n.add(id); return n; });

  let lastDay = "";
  return (
    <>
      <button className="audit-btn" aria-expanded={open} aria-controls="audit-panel" onClick={() => setOpen((o) => !o)}>
        <History size={14} aria-hidden /> Audit
      </button>
      {open && (
        <aside id="audit-panel" className="audit" aria-label="Audit trail">
          <button className="audit-close" onClick={() => setOpen(false)} aria-label="Close audit"><X size={16} /></button>
          <header className="audit-head">
            <span className="audit-layer"><History size={14} aria-hidden />Audit trail</span>
            <p className="audit-what">{WHAT[scope]}</p>
            <div className="audit-tabs" role="tablist">
              <button role="tab" aria-selected={!all} onClick={() => setAll(false)}>{page === "structure" ? `Structure · ${CP_LABEL[cp]}` : "Evidence"}</button>
              <button role="tab" aria-selected={all} onClick={() => setAll(true)}>Everything</button>
